'use client';

import { Dialog as DialogPrimitive, useDialog, useDialogContext } from '@ark-ui/react/dialog';
import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Dialog.module.css';

type DialogSize = 'sm' | 'md' | 'lg' | 'xl' | 'full';
type DialogPlacement = 'center' | 'top' | 'bottom';
type DialogScrollBehavior = 'outside' | 'inside';
type DialogContentProps = ComponentProps<typeof DialogPrimitive.Content> & {
  /** Width preset. `full` covers the viewport. */
  size?: DialogSize;
  /** Vertical position inside the positioner. */
  placement?: DialogPlacement;
  /** `outside` scrolls the positioner; `inside` caps the content and scrolls `DialogBody`. */
  scrollBehavior?: DialogScrollBehavior;
};
type DialogRootProps = ComponentProps<typeof DialogPrimitive.Root> & OverlayPortalProps;
type DialogRootProviderProps = ComponentProps<typeof DialogPrimitive.RootProvider> &
  OverlayPortalProps;

function Dialog({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: DialogRootProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <DialogPrimitive.Root lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props} />
    </OverlayPortalProvider>
  );
}

function DialogRootProvider({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: DialogRootProviderProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <DialogPrimitive.RootProvider
        lazyMount={lazyMount}
        unmountOnExit={unmountOnExit}
        {...props}
      />
    </OverlayPortalProvider>
  );
}

const DialogTrigger = forwardRef<
  ComponentRef<typeof DialogPrimitive.Trigger>,
  ComponentProps<typeof DialogPrimitive.Trigger>
>(function DialogTrigger(props, ref) {
  return <DialogPrimitive.Trigger ref={ref} {...props} data-slot="dialog-trigger" />;
});

const DialogBackdrop = forwardRef<
  ComponentRef<typeof DialogPrimitive.Backdrop>,
  ComponentProps<typeof DialogPrimitive.Backdrop>
>(function DialogBackdrop({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <DialogPrimitive.Backdrop
        ref={ref}
        className={clsx(styles.backdrop, className)}
        {...props}
        data-slot="dialog-backdrop"
      />
    </OverlayPortal>
  );
});

const DialogPositioner = forwardRef<
  ComponentRef<typeof DialogPrimitive.Positioner>,
  ComponentProps<typeof DialogPrimitive.Positioner>
>(function DialogPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <DialogPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="dialog-positioner"
      />
    </OverlayPortal>
  );
});

const DialogContent = forwardRef<ComponentRef<typeof DialogPrimitive.Content>, DialogContentProps>(
  function DialogContent(
    { className, placement = 'center', scrollBehavior = 'outside', size = 'md', ...props },
    ref,
  ) {
    return (
      <DialogPrimitive.Content
        ref={ref}
        className={clsx(styles.content, className)}
        {...props}
        data-size={size}
        data-placement={placement}
        data-scroll-behavior={scrollBehavior}
        data-slot="dialog-content"
      />
    );
  },
);

const DialogTitle = forwardRef<
  ComponentRef<typeof DialogPrimitive.Title>,
  ComponentProps<typeof DialogPrimitive.Title>
>(function DialogTitle({ className, ...props }, ref) {
  return (
    <DialogPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="dialog-title"
    />
  );
});

const DialogDescription = forwardRef<
  ComponentRef<typeof DialogPrimitive.Description>,
  ComponentProps<typeof DialogPrimitive.Description>
>(function DialogDescription({ className, ...props }, ref) {
  return (
    <DialogPrimitive.Description
      ref={ref}
      className={clsx(styles.description, className)}
      {...props}
      data-slot="dialog-description"
    />
  );
});

const DialogCloseTrigger = forwardRef<
  ComponentRef<typeof DialogPrimitive.CloseTrigger>,
  ComponentProps<typeof DialogPrimitive.CloseTrigger>
>(function DialogCloseTrigger(props, ref) {
  return <DialogPrimitive.CloseTrigger ref={ref} {...props} data-slot="dialog-close-trigger" />;
});

const DialogCloseIcon = forwardRef<
  ComponentRef<typeof CloseButton>,
  Omit<ComponentProps<typeof DialogPrimitive.CloseTrigger>, 'asChild'>
>(function DialogCloseIcon(
  { className, children, 'aria-label': ariaLabel = a11yLabels.closeDialog, ...props },
  ref,
) {
  return (
    <DialogPrimitive.CloseTrigger asChild {...props}>
      <CloseButton
        ref={ref}
        data-slot="dialog-close-icon"
        aria-label={ariaLabel}
        className={clsx(styles.closeIcon, className)}
      >
        {children}
      </CloseButton>
    </DialogPrimitive.CloseTrigger>
  );
});

const DialogHeader = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function DialogHeader({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.header, className)}
        {...props}
        data-slot="dialog-header"
      />
    );
  },
);

const DialogBody = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function DialogBody({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.body, className)}
        {...props}
        data-slot="dialog-body"
      />
    );
  },
);

const DialogFooter = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function DialogFooter({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.footer, className)}
        {...props}
        data-slot="dialog-footer"
      />
    );
  },
);

const DialogContext = DialogPrimitive.Context;

export {
  Dialog,
  DialogBackdrop,
  DialogBody,
  DialogCloseIcon,
  DialogCloseTrigger,
  DialogContext,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPositioner,
  DialogRootProvider,
  DialogTitle,
  DialogTrigger,
  useDialog,
  useDialogContext,
};
export type {
  DialogContentProps,
  DialogPlacement,
  DialogRootProps,
  DialogRootProviderProps,
  DialogScrollBehavior,
  DialogSize,
};

@layer moduix.components {
  .backdrop {
    position: fixed;
    z-index: calc(var(--z-index, var(--moduix-z-popup)) - 1);
    inset: 0;
    background-color: var(--moduix-backdrop-bg, var(--moduix-color-overlay));
    backdrop-filter: var(--moduix-backdrop-filter, blur(4px));

    &[data-state='open'] {
      animation: global(moduix-dialog-backdrop-in) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-dialog-backdrop-out) var(--moduix-transition-default) forwards;
    }
  }

  .positioner {
    box-sizing: border-box;
    position: fixed;
    z-index: var(--z-index, var(--moduix-z-popup));
    inset: 0;
    display: grid;
    /* Safe centering keeps the top of tall content reachable while the positioner scrolls. */
    place-items: safe center;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable both-edges;
    padding: var(--moduix-spacing-4);

    &:has(> [data-slot='dialog-content'][data-size='full']) {
      padding: 0;
    }
  }

  .content {
    --_dialog-width: 28rem;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    position: relative;
    width: min(
      var(--moduix-dialog-width, var(--_dialog-width)),
      calc(100vw - var(--moduix-spacing-8))
    );
    max-width: 100%;
    padding: var(--moduix-spacing-6);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    outline: 0;
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: center top;
    transition:
      scale var(--moduix-transition-default),
      translate var(--moduix-transition-default);

    /* Dims a parent dialog while a nested one is open. */
    &::after {
      content: '';
      position: absolute;
      z-index: 1;
      inset: 0;
      border-radius: inherit;
      background-color: rgb(0 0 0 / 0.05);
      opacity: 0;
      pointer-events: none;
      transition: opacity var(--moduix-transition-default);
    }

    &[data-size='sm'] {
      --_dialog-width: 24rem;
    }

    &[data-size='lg'] {
      --_dialog-width: 32rem;
    }

    &[data-size='xl'] {
      --_dialog-width: 36rem;
    }

    &[data-size='full'] {
      width: 100%;
      max-width: none;
      min-height: 100%;
      border-width: 0;
      border-radius: 0;
    }

    &[data-placement='top'] {
      align-self: start;
    }

    &[data-placement='bottom'] {
      align-self: end;
    }

    /* Inside scrolling caps the surface at the viewport and scrolls the body instead. */
    &[data-scroll-behavior='inside'] {
      display: flex;
      flex-direction: column;
      max-height: calc(100dvh - 2 * var(--moduix-spacing-4));

      & > [data-slot='dialog-body'] {
        flex: 1 1 auto;
        min-height: 0;
        overflow-y: auto;
      }
    }

    &[data-size='full'][data-scroll-behavior='inside'] {
      max-height: 100dvh;
    }

    &[data-has-nested] {
      scale: calc(1 - 0.05 * var(--nested-layer-count, 0));
      translate: 0 calc(var(--moduix-spacing-10) * var(--nested-layer-count, 0));

      &::after {
        opacity: 1;
      }
    }

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);
  }

  .title {
    margin: 0;
    font-size: var(--moduix-text-lg);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-lg);

    /* Keep long titles clear of the absolutely positioned close icon. */
    [data-slot='dialog-content']:has([data-slot='dialog-close-icon']) & {
      padding-inline-end: var(--moduix-spacing-7);
    }
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
  }

  /* The body inherits the content color; only the description is muted. */
  .body {
    margin-block-start: var(--moduix-spacing-4);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
  }

  .footer {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
    margin-block-start: var(--moduix-spacing-6);
  }

  .closeIcon {
    --moduix-close-button-radius: var(--moduix-radius-md);
    --moduix-close-button-color-hover: var(--moduix-color-popover-foreground);
    --moduix-close-button-bg-hover: var(--moduix-color-accent);
    position: absolute;
    z-index: 2;
    inset-block-start: var(--moduix-spacing-4);
    inset-inline-end: var(--moduix-spacing-4);
  }

  @media (prefers-reduced-motion: reduce) {
    .backdrop[data-state],
    .content[data-state] {
      animation-delay: 0ms;
      animation-duration: 1ms;
    }

    .content {
      transition: none;
    }
  }
}
